"""شمای جمع ← «تو» در رشته‌های رابط. فقط فایل‌های داده‌شده. diff را چاپ می‌کند."""
import re, sys, difflib
L = '\u0620-\u065F\u066E-\u06D5\u06FA-\u06FF\u200c'
def W(w): return re.compile(rf'(?<![{L}]){w}(?![{L}])')
IMP = {'بزنید':'بزن','ببینید':'ببین','بسازید':'بساز','بپیوندید':'بپیوند','بچینید':'بچین','بنویسید':'بنویس','بفرستید':'بفرست','بردارید':'بردار','بخوانید':'بخوان','بدهید':'بده','بگذارید':'بگذار','بگیرید':'بگیر','بیایید':'بیا','بروید':'برو','کنید':'کن','نکنید':'نکن','شوید':'شو','نشوید':'نشو','بمانید':'بمان','بکشید':'بکش','بپرسید':'بپرس','ببرید':'ببر','باشید':'باش','بیاورید':'بیاور','بزنيد':'بزن','بدانید':'بدان','بخواهید':'بخواه','بپذیرید':'بپذیر','بکنید':'بکن','بیفزایید':'بیفزا','بیفتید':'بیفت','بگویید':'بگو','بشنوید':'بشنو','بچسبانید':'بچسبان','بکشانید':'بکشان','برگردید':'برگرد','بمانيد':'بمان','دارید':'داری','ندارید':'نداری','هستید':'هستی','نیستید':'نیستی','بودید':'بودی','شما':'تو','کردید':'کردی','زدید':'زدی','دیدید':'دیدی','شدید_':'_','بسپارید':'بسپار','بیاورید':'بیاور','نشده‌اید':'نشده‌ای','فرستاده‌اید':'فرستاده‌ای','گواهی‌تان':'گواهی‌ات','همتایتان':'همتایت','هم‌کارتان':'هم‌کارت','مأموریتتان':'مأموریتت','سازمانتان':'سازمانت','گزارشتان':'گزارشت','درخواستتان':'درخواستت','بازخوردتان':'بازخوردت','برایتان':'برایت','بپرسید':'بپرس','بگویید':'بگو','داشتید':'داشتی','گرفتید':'گرفتی','دیدید':'دیدی','انداختید':'انداختی','نرسیدید':'نرسیدی','دهید':'بده','انظارید':'_','مطمئنید':'مطمئنی','هم‌کارید':'هم‌کاری','انتظارید':'انتظاری','دادید':'دادی','خواستید':'خواستی','کرده‌اید':'کرده‌ای','خودتان':'خودت','نزدیکتان':'نزدیکت','نامتان':'نامت','راهیارتان':'راهیارت','همراهتان':'همراهت','شهرستانتان':'شهرستانت','جوابتان':'جوابت','نظرتان':'نظرت','جنسیتتان':'جنسیتت','مسجدتان':'مسجدت','حسابتان':'حسابت','گوشیتان':'گوشی‌ات','کارتان':'کارت','نقشتان':'نقشت','پیامتان':'پیامت','شمارهٔ‌تان':'شماره‌ات'}
RULES = [(W(k), v) for k, v in IMP.items() if not k.endswith('_')]
RULES += [
  (re.compile(rf'(?<![{L}])(ن?می‌[{L}]+?)ید(?![{L}])'), r'\1ی'),
  (re.compile(rf'(?<![{L}])([{L}]+?ه)‌اید(?![{L}])'), r'\1‌ای'),
  (re.compile(rf'(?<![{L}])([{L}]+?)‌تان(?![{L}])'), r'\1‌ات'),
]
def conv(t):
    for r, v in RULES: t = r.sub(v, t)
    t = re.sub(rf'(?<![{L}])(ن?)می‌(آ|گو|افزا|نما|پا|زدا|گشا)ی(?![{L}])', r'\1می‌\2ید', t)
    return t
for p in sys.argv[1:]:
    s = open(p, encoding='utf-8').read(); n = conv(s)
    if n != s:
        open(p, 'w', encoding='utf-8').write(n)
        for l in difflib.unified_diff(s.splitlines(), n.splitlines(), lineterm='', n=0):
            if l.startswith(('+', '-')) and not l.startswith(('+++', '---')): print(p.split('/')[-1][:12], l[:230])
